// Minimal endless runner for canvas with id "game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = (canvas.width = canvas.offsetWidth || 800);
  const H = (canvas.height = canvas.offsetHeight || 200);
  const GROUND = H - 30;
  let speed = 3;
  let score = 0;
  let running = true;

  const player = {
    x: 50,
    y: GROUND - 20,
    w: 20,
    h: 20,
    vy: 0,
    onGround: true,
    crouch: false,
    draw() {
      ctx.fillStyle = '#0077ff';
      const ph = this.crouch ? this.h / 2 : this.h;
      ctx.fillRect(this.x, this.y + (this.h - ph), this.w, ph);
    },
    update() {
      if (!this.onGround) {
        this.vy += 0.5; // gravity
        this.y += this.vy;
        if (this.y + this.h >= GROUND) {
          this.y = GROUND - this.h;
          this.vy = 0;
          this.onGround = true;
        }
      }
    },
    jump() {
      if (this.onGround) { this.vy = -10; this.onGround = false; }
    },
    slide(start) {
      this.crouch = start;
    },
  };

  const obstacles = [];
  function spawnObstacle() {
    // random type: spike (tall) or gap (hole)
    const type = Math.random() < 0.7 ? 'spike' : 'gap';
    if (type === 'spike') {
      const w = 20 + Math.random() * 30;
      const h = 20 + Math.random() * 30;
      obstacles.push({ x: W, y: GROUND - h, w, h, type });
    } else {
      // gap: we represent as a tall invisible block; collision when player falls into it
      const w = 30 + Math.random() * 20;
      obstacles.push({ x: W, y: GROUND, w, h: 999, type }); // treat as hole
    }
  }
  let spawnTimer = 0;

  function checkCollision(obs) {
    if (obs.type === 'spike') {
      return (
        player.x < obs.x + obs.w &&
        player.x + player.w > obs.x &&
        player.y < obs.y + obs.h &&
        player.y + player.h > obs.y
      );
    } else { // gap
      // player is on ground; if over gap, it's a loss
      const overGap = player.x + player.w > obs.x && player.x < obs.x + obs.w;
      return overGap && player.y + player.h >= GROUND;
    }
  }

  function loop() {
    if (!running) return;
    ctx.clearRect(0, 0, W, H);
    // ground
    ctx.fillStyle = '#444';
    ctx.fillRect(0, GROUND, W, H - GROUND);

    // update and draw player
    player.update();
    player.draw();

    // spawn obstacles
    spawnTimer -= speed;
    if (spawnTimer <= 0) {
      spawnObstacle();
      spawnTimer = 100 + Math.random() * 100; // distance until next
    }

    // move obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= speed;
      // draw spike
      if (o.type === 'spike') {
        ctx.fillStyle = '#ff3300';
        ctx.fillRect(o.x, o.y, o.w, o.h);
      }
      // check collision
      if (checkCollision(o)) {
        running = false;
        ctx.fillStyle = 'rgba(0,0,0,0.7)';
        ctx.fillRect(0, 0, W, H);
        ctx.fillStyle = '#fff';
        ctx.font = '24px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Game Over', W / 2, H / 2);
        ctx.fillText(`Score: ${Math.floor(score)}` , W / 2, H / 2 + 30);
        return;
      }
      // remove off-screen
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }

    // increase difficulty
    speed += 0.001;
    score += speed;
    // draw score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${Math.floor(score)}`, 10, 20);

    requestAnimationFrame(loop);
  }

  // controls
  window.addEventListener('keydown', e => {
    if (e.code === 'Space') player.jump();
    if (e.code === 'ArrowDown') player.slide(true);
  });
  window.addEventListener('keyup', e => {
    if (e.code === 'ArrowDown') player.slide(false);
  });

  // start game
  loop();
})();
